INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_122'), 1, 'Before you look at any output: can you tell, from the assertion definition alone, whether this assertion can be checked? What should the case become if one of its assertions cannot be checked, and what should that do to the score?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_122'), 2, 'Split the work in two passes per case. First a validate step (weight, assertions array, then each assertion''s type and parameters, compiling the regex inside try/catch and walking the schema recursively to reject unknown keywords). Then, only for valid cases, a check step that starts with `if (output === null) return false`. Keep slice counters in a Map and sort its keys at the end.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_122'), 3, 'A similar runner with other types: for `{ "type": "starts_with", "value": "" }` the validate step returns bad_definition (an empty prefix matches everything), so the case is invalid and its weight is not added anywhere. For two valid cases with weights 1 and 3, where only the first passes, the score is 1 / (1 + 3) = 0.25, and their slice reports passed 1, total 2, rate 0.5.');
