VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_122'), 'Grader JSON passes; prose before the JSON fails is_json, json_schema and score_in_range', '{"cases":[{"id":"g1","slice":"python/easy","weight":1,"output":"{\"verdict\":\"pass\",\"score\":86,\"feedback\":\"Correct and readable. Consider a guard for an empty list.\",\"issues\":[\"no empty-list guard\"]}","assertions":[{"type":"is_json"},{"type":"json_schema","schema":{"type":"object","required":["verdict","score","feedback"],"properties":{"verdict":{"type":"string","enum":["pass","needs_work"]},"score":{"type":"integer","minimum":0,"maximum":100},"feedback":{"type":"string"},"issues":{"type":"array","items":{"type":"string"}}}}},{"type":"score_in_range","path":"score","min":0,"max":100},{"type":"not_contains","value":"def solve("},{"type":"max_length","value":600}]},{"id":"g2","slice":"python/easy","weight":1,"output":"Sure! Here is the grade:\n{\"verdict\":\"pass\",\"score\":90,\"feedback\":\"Clean loop.\"}","assertions":[{"type":"is_json"},{"type":"json_schema","schema":{"type":"object","required":["verdict","score","feedback"],"properties":{"verdict":{"type":"string","enum":["pass","needs_work"]},"score":{"type":"integer","minimum":0,"maximum":100},"feedback":{"type":"string"},"issues":{"type":"array","items":{"type":"string"}}}}},{"type":"score_in_range","path":"score","min":0,"max":100},{"type":"not_contains","value":"def solve("},{"type":"max_length","value":600}]},{"id":"g3","slice":"typescript/hard","output":"{\"verdict\":\"needs_work\",\"score\":45,\"feedback\":\"Empty array input crashes reduce() without an initial value.\"}","assertions":[{"type":"is_json"},{"type":"equals_field","path":"verdict","value":"needs_work"},{"type":"contains","value":"empty array","ignoreCase":true}]}]}', '{"cases":[{"id":"g1","status":"pass","failed":[]},{"id":"g2","status":"fail","failed":["is_json","json_schema","score_in_range"]},{"id":"g3","status":"pass","failed":[]}],"invalid":[],"slice