-- challenge chal_quiz_lle_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_131', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-1-3' AND is_deleted = false LIMIT 1), 'judge-agreement-and-position-bias-quiz', 'Can this judge be trusted?', 'Two calibration results for LLM judges on the grading assistant: two judges compared by raw agreement, and a pairwise comparison run in both orders.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_131'), 'Two candidate judges were calibrated against mentor labels (pass/fail) on two different calibration sets of 100 submissions each. Rows are mentor labels, columns judge labels.

judge-A (set with many hard challenges)
                judge: pass   judge: fail
human: pass          44             6
human: fail           6            44

judge-B (set of mostly easy challenges)
                judge: pass   judge: fail
human: pass          90             3
human: fail           5             2

Statement: "judge-B agrees with the mentors better than judge-A, because it agrees on 92% of the submissions and judge-A on only 88%."', 'single_choice'::question_type, 'False. Raw agreement ignores the agreement chance alone would produce. judge-A: po = 0.88, pe = 0.5 x 0.5 + 0.5 x 0.5 = 0.5, kappa = (0.88 - 0.5) / 0.5 = 0.76. judge-B: po = 0.92, pe = 0.93 x 0.95 + 0.07 x 0.05 = about 0.887, kappa = (0.92 - 0.887) / 0.113 = about 0.29. judge-B mostly agrees because almost everything is pass; it catches 2 of the 7 submissions mentors failed. Kappa corrects for the label frequencies, which also differ between the two sets, so comparing the raw percentages compares the sets as much as the judges. The misconception is that a higher percentage of agreement always means a better judge.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_131'), 'The pairwise judge compared feedback from grader-v9 and grader-v8 for the same six submissions, once with v9 shown first and once with v8 shown first. Winner named by content:

pair   v9 shown first   v8 shown first
p1     v9               v8
p2     v9               v9
p3     v9               v8
p4     v8               v8
p5     v9               v8
p6     v9               v9

The original report used only the first column: "v9 wins 5 of 6".

Statement: "In half of the pairs the winner followed the position rather than the content, so a comparison that always shows v9 first overstates how often v9 is better."', 'single_choice'::question_type, 'True. In p1, p3 and p5 the judge picked whichever answer was shown first in both runs: v9 when v9 was first, v8 when v8 was first. Those three flips (50% of the pairs) say nothing about content, and in a one-order run they all count for the answer in first position - here v9. Counting only pairs where both orders agree leaves p2 and p6 for v9 and p4 for v8: 2 to 1 on three pairs, a much weaker result than 5 of 6. Run both orders and treat flips as ties. The misconception is that a fixed order is neutral because the same order is used for every pair; a consistent position preference turns into a consistent advantage.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_lle_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_lle_132', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-1-3' AND is_deleted = false LIMIT 1), 'judge-human-agreement-kappa', 'Judge-human agreement: Cohen''s kappa and bias flags', 'Before an LLM judge may replace mentor spot-checks on the grading assistant, the calibration report must show how well its labels agree with the mentors'' labels, per slice, and whether it has position or verbosity bias. Write compare(categories, items, swaps). No model is called: judge and mentor labels and the swap experiment are recorded.

categories must be a non-empty array of unique strings or numbers, otherwise the report is { "error": "bad_categories" }. Labels are compared with === (the string "4" is not the category 4). An item counts only when both human and judge are categories; any other item is skipped (counted in skipped, not a disagreement). For a group of items: n = counted items, matrix[h][j] = items labelled categories[h] by the human and categories[j] by the judge (rows human, columns judge, in categories order), observed = diagonal / n, expected = sum over categories of (row total / n) x (column total / n), kappa = (observed - expected) / (1 - expected) from unrounded values. n = 0: observed, expected, kappa null and reason "no_items". All counted labels (both raters) in one single category: kappa null and reason "single_category" (observed and expected still reported). Otherwise reason null.

overall = the agreement over all items with its matrix; slices = { slice, n, skipped, observed, expected, kappa, reason } per slice (missing or empty = "(none)"), sorted by name, without matrix.

Swap experiment: original (A shown first) and swapped (B shown first) name the winner by content, "A", "B" or "tie"; the two answers make the same points and longer ("A" or "B") is the padded one. Records with other values are skipped. pairs = valid records; a flip is original !== swapped; flipRate = flips / pairs. A flip with original A and swapped B is a first-position win, original B and swapped A a second-position win; preferredPosition is the more frequent one, null on a tie. positionBias: flips / pairs > 0.2. consistent = pairs - flips; longerWins = consistent pairs won by the longer answer; verbosityRate = longerWins / consistent; verbosityBias: longerWins / consistent > 0.5. A rate with denominator 0 is null and its flag false. bias = { pairs, skipped, flips, flipRate, preferredPosition, positionBias, consistent, longerWins, verbosityRate, verbosityBias }.

Round observed, expected, kappa, flipRate and verbosityRate with Math.round(x * 1000) / 1000. Input: { categories, items, swaps }. Output: { overall, slices, bias } as JSON (the full rules are at the top of the starter).', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_132'), 1, 'Which items can tell you anything about agreement? And if every counted label from both raters is the same category, what does the formula for kappa compute, and what should the report say instead?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_132'), 2, 'Build the matrix with categories.indexOf(label) for the human (row) and the judge (column); a -1 on either side means the item is skipped. Row totals, column totals and the diagonal give everything else. For slices, group the items in a Map first and run the same function on each group. In the swap records, compare original with swapped before you look at longer.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_132'), 3, 'A worked example with other numbers: categories ["yes", "no"], matrix [[6, 2], [1, 1]] (n = 10). observed = (6 + 1) / 10 = 0.7; row totals 8 and 2, column totals 7 and 3, so expected = 0.8 x 0.7 + 0.2 x 0.3 = 0.62; kappa = (0.7 - 0.62) / 0.38 = 0.211 after rounding. A swap record { original: "B", swapped: "A" } is a flip won by the second position; { original: "A", swapped: "A", longer: "A" } is consistent and won by the longer answer.');
