-- challenge chal_quiz_lle_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_211', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-2-1' AND is_deleted = false LIMIT 1), 'regression-gate-quiz', 'Read the gate report: v6 against v7', 'Two reports from the regression gate that compares the grading prompt v6 with v7 on the same recorded cases: one with a small slice that moved a lot, one with an overall drop under the limit.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_211'), 'CI ran the grading eval set with prompt v6 and with prompt v7 on the same recorded cases. Gate config: minSampleSize 30, maxSliceDropPp 5, maxOverallDropPp 2.

group            n     v6      v7     delta  pass->fail  fail->pass
overall        612   81.4%   81.0%   -0.3       9           7
py-loops       214   83.6%   84.1%   +0.5       2           3
sql-joins      386   80.3%   80.1%   -0.3       5           4
rust-ownership  12   75.0%   58.3%  -16.7       2           0

Statement: "The gate should fail v7, because the rust-ownership slice dropped 16.7 pp, more than the 5 pp slice limit."', 'single_choice'::question_type, 'False. The rust-ownership slice has 12 paired cases, below the minimum sample of 30, so the gate reports it as "insufficient data" and does not apply the drop limit to it. The 16.7 pp is two cases that flipped from pass to fail; with 12 cases, one flip moves the rate by 8.3 pp, so the number is mostly noise. The right outcome is not "pass" either: the slice is listed as a reason for review, and the fix is to add more Rust ownership cases to the eval set before the next comparison. The misconception is reading a percentage without its n: a big delta on a tiny slice is not a measurement.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_211'), 'The same gate on the full eval set (maxOverallDropPp 2, minSampleSize 30). Every case was graded by both versions.

group     n      v6      v7     delta  pass->fail  fail->pass
overall  2400   81.0%   80.2%   -0.8      31          12

criticalPassToFail (excerpt, m = pass->fail + fail->pass):
m=41 -> 27   m=42 -> 27   m=43 -> 28   m=44 -> 28

Rule: v7 is a significant regression when pass->fail >= criticalPassToFail[m].

Statement: "Although the overall drop of 0.8 pp is under the 2 pp limit, the paired rule marks v7 as a significant regression."', 'single_choice'::question_type, 'True. Only the 43 cases that changed result carry information about the difference between v6 and v7; the other 2357 passed or failed with both prompts. If the two prompts were equally good, a flipped case would be equally likely to go either way, like a coin. Here 31 of the 43 went from pass to fail, and the table says 28 or more out of 43 is unlikely by chance (a one-sided sign test at 5%). The drop limit asks "is the change big enough to matter?" and the paired rule asks "is it real?": a small but consistent drop can be real. The misconception is that a drop under the threshold means "no regression".', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_lle_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_lle_212', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-2-1' AND is_deleted = false LIMIT 1), 'prompt-regression-gate', 'A regression gate for prompt v6 vs v7', 'Prompt v7 of the CodeDev grading assistant looked better than v6 on five hand-picked submissions and was worse on the 500-case eval set. From now on CI runs the eval set on recorded outputs with both prompts and a gate decides. Write regressionGate(input). Input (JSON): { baseline: { version, results }, candidate: { version, results }, config: { maxOverallDropPp, maxSliceDropPp, minSampleSize, criticalPassToFail } }, where results is an array of { caseId, slice, pass } and the limits are whole numbers of percentage points.

1. Validation. A caseId that appears more than once in one run, or a case present in both runs with a different slice, makes the input invalid. Return { "decision": "invalid", "reasons": [...] } listing every problem in this order: duplicates in the baseline in input order ("duplicate case <id> in baseline", one reason per extra occurrence), then duplicates in the candidate ("duplicate case <id> in candidate"), then slice mismatches in baseline order ("case <id>: slice <a> in baseline, <b> in candidate"; compare the first occurrence in each run).
2. Pairing. Compare only cases present in both runs (pair them by caseId, not by position: the candidate results come in a different order). paired = number of paired cases; unpaired = number of distinct caseIds found in only one run.
3. Statistics for the overall group (all paired cases) and for each slice (sorted by name, plain string comparison): n; baseline and candidate pass rates = Math.round(1000 * passes / n) / 10; delta = Math.round(1000 * (candidatePasses - baselinePasses) / n) / 10 (rates and delta are null when n is 0); passToFail and failToPass = paired cases that passed with the baseline and failed with the candidate, and the reverse.
4. Checks. A group with n < minSampleSize gets status "insufficient data" and no further check. Otherwise its pass rate dropped more than its limit when 100 * (baselinePasses - candidatePasses) > limit * n (exact integer comparison; a drop equal to the limit is allowed). The limit is maxOverallDropPp for the overall group and maxSliceDropPp for a slice. For the overall group only, the paired sign rule: with m = passToFail + failToPass, v7 is a significant regression when m >= 1, criticalPassToFail[m] is a number (the table may hold null) and passToFail >= criticalPassToFail[m]. The table has an entry for every m from 0 to the number of paired cases. Status is "regressed" when a check fires, "ok" otherwise.
5. reasons: the overall group first, then the slices in name order; within the overall group the drop before the sign rule. The drop is printed as -delta (as JavaScript prints numbers): "overall: insufficient data (n=5 < 30)", "overall: pass rate dropped 2.7 pp (limit 2)", "overall: significant regression (31 pass->fail vs 12 fail->pass, critical 28)", "slice sql-joins: insufficient data (n=12 < 30)", "slice sql-joins: pass rate dropped 8.3 pp (limit 5)".
6. decision: "fail" when any group is regressed, otherwise "review" when any group has insufficient data (too few cases is never a pass), otherwise "pass".

Output (printed by the runner): { decision, paired, unpaired, overall: { n, baseline, candidate, delta, passToFail, failToPass, status }, slices: [{ slice, n, baseline, candidate, delta, passToFail, failToPass, status }], reasons }. Up to 1,000 cases per run.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_212'), 1, 'Before any percentage: which cases can tell you something about v7 compared with v6? A case that only one run graded, or a case that passed (or failed) with both prompts - what does each contribute to the decision, and to which number?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_212'), 2, 'Index each run by caseId in a Map while you look for duplicates, then walk the baseline map to build the pairs. Every number in the report comes from four counts per group (n, baseline passes, candidate passes, the two kinds of flips). Check the order of the decisions: the minimum sample first, then the integer drop comparison, then the table lookup, which uses the number of flipped cases, not n.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_212'), 3, 'A worked example on other numbers: a slice ts-types with 50 paired cases, minSampleSize 30, slice limit 5, baseline 44 passes, candidate 41 passes, 6 pass->fail and 3 fail->pass. Rates 88 and 82, delta -6. The drop check is 100 * 3 = 300 > 5 * 50 = 250, so the slice is regressed with the reason "slice ts-types: pass rate dropped 6 pp (limit 5)". If this were the overall group with a table entry of 8 for m = 9, the sign rule would not fire, because 6 < 8.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_212'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
