-- lesson 2.2: Tracing LLM calls: tokens, latency, model & cost (Sanity lesson-lle-2-2)
UPDATE course.lesson SET title = 'Tracing LLM calls: tokens, latency, model & cost', order_index = 2, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 2 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-2-2' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 2 AND is_deleted = false LIMIT 1), 'Tracing LLM calls: tokens, latency, model & cost', 'sanity', 'lesson-lle-2-2', 2
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-lle-2-2' AND is_deleted = false);

-- challenge chal_quiz_lle_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_221', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-2-2' AND is_deleted = false LIMIT 1), 'tracing-llm-calls-quiz', 'Read the traces of the grading assistant', 'Three pieces of evidence from the traces and dashboards of the grading assistant: a grading request with a retry, a truncated answer, and a cost panel built from sampled spans.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_221'), 'One grading request, as shown in the trace viewer (attribute names follow the experimental OpenTelemetry GenAI conventions; codedev.* are the team''s own):

grade_submission  sub_88412                                  4.9 s
  chat grader-large   codedev.attempt=1  gen_ai.usage.input_tokens=1840  gen_ai.usage.output_tokens=512  gen_ai.response.finish_reasons=["length"]   2.1 s
  chat grader-large   codedev.attempt=2  gen_ai.usage.input_tokens=1840  gen_ai.usage.output_tokens=690  gen_ai.response.finish_reasons=["stop"]     2.6 s

Price table (config/llm-prices.json): grader-large input $0.40 and output $1.60 per million tokens.

Statement: "The model cost of grading this submission is about $0.0018."', 'single_choice'::question_type, 'False. $0.0018 is the cost of the second chat span only: 1840 x 0.40 / 1,000,000 + 690 x 1.60 / 1,000,000 = $0.000736 + $0.001104 = $0.00184. The first attempt was cut off by the output limit (finish reason "length") and thrown away by the application, but the provider still processed its 1840 input tokens and generated its 512 output tokens: $0.000736 + $0.000819 = $0.00156. The request cost about $0.0034, almost twice the figure in the statement. This is why every attempt gets its own span with its own token counts, and why the cost of a feature is the sum over all calls, retries included. The misconception is that a failed or discarded attempt is free.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_221'), 'A span from the hint generator, followed by the application error logged under the same trace id:

chat grader-small  2.8 s
  gen_ai.request.model = grader-small
  gen_ai.request.max_tokens = 512
  gen_ai.usage.input_tokens = 2210
  gen_ai.usage.output_tokens = 512
  gen_ai.response.finish_reasons = ["length"]
  codedev.prompt.version = hints-v3

ERROR hints: cannot parse model output as JSON: Unexpected end of JSON input (trace 4bf92f3577b34da6a3ce929d0e0e4736)

Statement: "The span shows that the model stopped because it reached the output token limit, which explains why the JSON was incomplete."', 'single_choice'::question_type, 'True. Three attributes agree: the request allowed 512 output tokens, the model produced exactly 512, and the finish reason is "length" (cut off by the limit) rather than "stop" (the model ended its answer). A JSON document cut off in the middle ends early, which is what "Unexpected end of JSON input" means. The fix belongs in the call (a higher limit, a shorter output format, or detecting "length" and handling it), not in the parser. The misconception is to treat every parse error as "the model returned bad JSON"; without the finish reason on the span, this would have looked like random model misbehaviour.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_221') AND order_index = 2)
    RETURNING id
)
