VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_232'), 1, 'What makes two occurrences "the same value" for each type? Write that key down per type (lowercase email, the 9 digits after the prefix, the folded name) before you write any regex - the numbering and the counts follow from it.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_232'), 2, 'Look at three places: a Map from type plus key to its number, filled in order of first appearance; the characters around each number match (lookbehind (?<!...) and lookahead (?!...) do this in one regex, \b does not, because it treats "-" as a boundary); and for names, a folded copy of the text that you search while you copy the original characters into the result.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_232'), 3, 'A worked example on other data: with the key "digits of a 6-digit ticket number", the text "T 123456, t-123456, 123 456, 123456" redacted with the rule "no letter, digit, _ or - right before or after" gives "T [TICKET_1], t-123456, 123 456, [TICKET_1]" with count 2: the hyphenated one touches "-", and the spaced one is not 6 consecutive digits.');
