       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_232'), 'Course ids, submission ids, timestamps and long numbers are not personal data', '{"roster":["Lê Minh Khoa"],"text":"ts=2026-10-27T09:15:42.120Z epoch_ms=1793025136120 trace=4bf92f3577b34da6a3ce929d0e0e4736 course=course_079203001234 submission=sub-202610270915 lesson=lesson-lle-2-3 challenge=chal_coding_lle_232 build=v0.9.12 score=0.85 tokens=1840 id_number=079203001234 counter=09123456789 user=Lê Minh Khoa"}', '{"text":"ts=2026-10-27T09:15:42.120Z epoch_ms=1793025136120 trace=4bf92f3577b34da6a3ce929d0e0e4736 course=course_079203001234 submission=sub-202610270915 lesson=lesson-lle-2-3 challenge=chal_coding_lle_232 build=v0.9.12 score=0.85 tokens=1840 id_number=[NATIONAL_ID_1] counter=09123456789 user=[NAME_1]","counts":{"EMAIL":0,"NATIONAL_ID":1,"PHONE":0,"NAME":1}}', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_232'), 'Name boundaries: Anh is not An, longer roster names win, Đ folds to d', '{"roster":["Lê An","Trần Bình","Trần Bình An","Đặng Thu Hà"],"text":"Lê Anh asked a question. Trần Bình An and Trần Bình worked together; DANG THU HA reviewed it (dang thu ha, Đặng Thu Hà). Lê An: \"Lê An\" is my name. Thanh Lê Annabelle is not on the roster."}', '{"text":"Lê Anh asked a question. [NAME_1] and [NAME_2] worked together; [NAME_3] reviewed it ([NAME_3], [NAME_3]). [NAME_4]: \"[NAME_4]\" is my name. Thanh Lê Annabelle is not on the roster.","counts":{"EMAIL":0,"NATIONAL_ID":0,"PHONE":0,"NAME":7}}', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_232'), 'Nothing to redact: Vietnamese feedback comes back unchanged', '{"roster":["Võ Thị Sáu"],"text":"Bài làm của bạn đúng 4/5 test. Hãy kiểm tra trường hợp mảng rỗng (len(a) == 0) và số âm. Điểm: 8.5/10 - chấm lúc 2026-10-27 09:15."}', '{"text":"Bài làm của bạn đúng 4/5 test. Hãy kiểm tra trường hợp mảng rỗng (len(a) == 0) và số âm. Điểm: 8.5/10 - chấm lúc 2026-10-27 09:15.","counts":{"EMAIL":0,"NATIONAL_ID":0,"PHONE":0,"NAME":0}}', 2, false, true, 5),
