-- challenge chal_coding_lle_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_lle_322', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-3-2' AND is_deleted = false LIMIT 1), 'data-vs-instructions-prompt-builder', 'A prompt builder that keeps data out of the instructions', 'The CodeDev learning assistant answers questions about a learner''s submission. One prompt now carries several untrusted inputs - the submission, the learner''s question and course notes found by retrieval - and an injected note recently made the assistant paste a reference solution. Write buildPrompt(request, nextId) that returns { prompt, manifest }. The prompt is the instruction lines (as given), then the line DATA_NOTE (a constant in the file), then one block per input, in input order: a line "<<<DATA name=<name> boundary=<boundary>>>>", the content, a line "<<<END boundary=<boundary>>>>". For each input: (1) boundary: call nextId(); if the id is already used by an earlier block of this prompt, call it again until it is not. (2) content: normalise with String.prototype.normalize("NFKC"), then replace every "<" with "&lt;" and every ">" with "&gt;". (3) budget: if the escaped content has more than maxChars characters, counted as Unicode code points (Array.from), keep the first maxChars and add, after it and inside the block, the line "[truncated: kept <maxChars> of <total> characters]". Manifest entry per input: { name, boundary, chars (code points of the original content), sentChars (code points kept, without the truncation line), truncated, escaped (number of < and > replaced in the whole normalised content), normalised (true when NFKC changed the content) }. Before building, validate the inputs in order and throw an Error with the exact message: a name not matching /^[a-z][a-z0-9_-]{0,31}$/ -> invalid name "<name>"; a name used twice -> duplicate name "<name>"; maxChars not an integer >= 1 -> invalid maxChars for "<name>". Input: { instructions: string[], inputs: [{ name, content, maxChars }], ids: string[] } (the id source returns the ids in order). Output: { manifest, model } where model is how the fake model reads your prompt (after NFKC, line by line: the instructions it would follow, the blocks it saw, an unclosed block), or { error }. The hidden tests use fake closing lines, nested delimiters, look-alike characters, a large note, repeated ids, emoji and invalid inputs.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
