INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_322'), 1, 'For every test, the model''s "instructions" should be exactly your instruction lines plus DATA_NOTE, whatever the inputs contain. Which characters would a learner need to write to make the model see a line outside a block, and does the model see the same characters you escaped?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_322'), 2, 'Look at the first line of fakeModel: it normalises the whole prompt before it reads it. Then look at the order of your steps: normalise, escape, count and cut, in that order - and count with Array.from, not .length, because an emoji is one code point but two UTF-16 units.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_322'), 3, 'A similar worked example on different input: content "ｘ＜y" with maxChars 3. NFKC gives "x<y" (normalised: true), escaping gives "x&lt;y" (escaped: 1, 6 code points), so the block holds "x&l" and the line "[truncated: kept 3 of 6 characters]"; the manifest says chars 3, sentChars 3, truncated true. With ids ["a", "a", "b"] and two inputs, the boundaries are "a" and "b".');
