-- challenge chal_quiz_lle_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_331', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-3-3' AND is_deleted = false LIMIT 1), 'validate-model-output', 'Validating a model''s score', 'Two statements about the grading service after the gradebook was corrupted by model replies: one about a one-line "repair" of the score, one about capping the AI score with the automated tests.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_331'), 'Hotfix proposed in the incident channel (services/grading/aiGrade.ts):
const out = JSON.parse(reply.text);
const score = Math.min(10, Math.max(0, Math.round(Number(out.score))));
await db.query("UPDATE submissions SET ai_score = $1, ai_feedback = $2 WHERE id = $3", [score, out.feedback, id]);

Model replies seen this week:
{"score": "10/10", "feedback": "Great work"}
{"score": 11, "feedback": "Exceeds expectations"}
{"score": -1, "feedback": "Could not grade: the code does not compile"}
{"feedback": "Good structure, but ties are not handled."}

Statement: "With this hotfix every reply becomes a correct score from 0 to 10, so the gradebook is safe."', 'single_choice'::question_type, 'False. Number("10/10") and Number(undefined) are NaN, and Math.round, Math.max and Math.min all return NaN for NaN, so two of these replies still write NaN (PostgreSQL''s numeric type even accepts ''NaN''). The other two are worse because they look fine: 11 silently becomes 10, and -1 - the model''s way of saying it could not grade - becomes 0, a failing grade the learner did not earn. Clamping turns an invalid reply into a valid-looking one and erases the evidence. Reject the reply, keep the AI score empty, send the submission to human review with the reason, and record the decision. The misconception is that coercing a value into range is the same as validating it.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_331'), 'Grading policy (v2): an AI score is accepted only if it is an integer 0-10 and at most the automated test score + 2; otherwise the submission goes to human review.

Decision log:
submission  tests  model reply                                  decision
sub_91c2    3/10   {"score": 9, "feedback": "Perfect solution."}  review (above_test_cap)
sub_91c3    7/10   {"score": 8, "feedback": "Clear names, ..."}    accepted

Statement: "Under this policy, a prompt injection that makes the model return 10 on a submission passing 3 of 10 tests can no longer put more than 5 in the gradebook: the reply goes to a human instead."', 'single_choice'::question_type, 'True. The cap ties the AI score to evidence the learner cannot talk to: the automated tests. With 3 of 10 tests, the highest AI score that is accepted is 5, and any higher reply - a 9 as in sub_91c2, or the injected 10 from lesson 3.1 - is not written but routed to review with the reason above_test_cap. The cap does not detect the injection; it limits what a successful one is worth, and the review queue turns it into a signal. The decision log is what lets you prove this later. The misconception is that output validation is only about the format of the reply.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_lle_332 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_lle_332', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-3-3' AND is_deleted = false LIMIT 1), 'validate-model-output', 'Fix It: a Model Score Written Straight to the Database', 'The CodeDev grading service asks the AI grader for JSON { "score": <integer 0-10>, "feedback": "<text>" } and handleGradingResult writes the reply straight into the gradebook (UPDATE submissions SET ai_score = output.score). Since the new grading prompt went live the gradebook shows scores of 11, -1 and 9.5, submissions that stay without a score, and grading jobs that fail with invalid input syntax for type numeric: "10/10" until they are dead-lettered. Fix handleGradingResult so that a reply is never repaired: it is accepted only when it is a JSON object whose score is an integer from 0 to 10, whose feedback is a string of 10 to 1000 characters after trimming, and whose score is at most the automated test score + 2. An accepted reply is written with db.updateAiScore(id, score, feedback). Any other reply leaves the AI score empty and goes to human review with db.sendToReview(id, reason), where reason is the first failed check, in this order: invalid_json (not JSON, or not a JSON object), score_missing (absent or null), score_not_integer (not a JSON number, or not an integer), score_out_of_range, feedback_missing (not a string), feedback_length, above_test_cap. Every job records exactly one decision with db.recordDecision({ submissionId, outcome: "accepted" | "review", reason }) (reason null when accepted). Do not change the database fake or the test runner. Input: { jobs: [{ submissionId, testScore, modelOutput }] }. Output: the gradebook, the review queue, the decisions and the jobs that threw. The public tests include the replies from the incident; the hidden tests cover decimals, strings, non-JSON replies, feedback limits, the test cap and a large recorded batch.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
