INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_332'), 1, 'What does the database do with a value that is not a valid score? Run the starter on the incident test and compare the gradebook with the failures: which bad replies crash the job, and which ones are quietly stored?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_332'), 2, 'Everything happens in handleGradingResult: JSON.parse can throw, output.score can be any JSON value, and updateAiScore is called before anything is checked. Look at the order of the checks in the header comment: write one function that returns the first failed reason or null, and only call updateAiScore when it returns null.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_332'), 3, 'A similar case on different data: a reply for a difficulty estimate must be { "level": integer 1-5 }. {"level": "3"} fails as level_not_integer (a string is not a JSON number), {"level": 4.5} fails the same way, {"level": 6} fails as level_out_of_range, and none of them is rounded or clamped: each goes to review with its reason and a decision is recorded, while {"level": 3} is written as 3.');
