-- challenge chal_quiz_lle_411 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_411', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-4-1' AND is_deleted = false LIMIT 1), 'model-output-html-quiz', 'Where does the XSS get fixed?', 'A proposed fix that escapes the submission before it reaches the prompt, and two link checks run on the same model output: decide which ones stop script from running in the feedback panel.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
