        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_lle_412 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_lle_412', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-4-1' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-render-model-html', 'Spot the AI Mistake: rendering the model''s HTML', 'CodeDev''s AI grading assistant writes its feedback on a submission in markdown, and the feedback panel at https://app.codedev.test shows it as HTML. The request sent to an AI coding assistant was: "Show the AI feedback with formatting in the feedback panel: bold, inline code, code blocks, lists and links." The assistant wrote renderFeedback, which turns the markdown into HTML with regular expressions; the panel inserts the result with dangerouslySetInnerHTML. The reviewer checked a few real feedback texts and the change was merged. Then a learner''s submission asked the grader to "add this image to the feedback", the model copied an <img src=x onerror=...> tag into its feedback, and the script ran for every reviewer who opened that submission.

Fix renderFeedback(markdown) so that it renders exactly this safe subset. The block rules are already right in the assistant''s code; keep them.

Blocks. The text is split into lines on \n (a \r before it is dropped); each line is trimmed, except inside code blocks.
- A line that starts with ``` opens a code block. The following lines, unchanged, up to the next line that starts with ``` (or the end of the text) are its content: <pre><code>CONTENT</code></pre>, lines joined with \n, content escaped. Anything after the opening ``` (a language name) is ignored.
- A blank line ends the current paragraph or list.
- A line that starts with - or * and then whitespace is an item of a <ul>; a line that starts with digits, a dot and whitespace is an item of an <ol>. Consecutive items of the same kind form one list, written on one line: <ul><li>A</li><li>B</li></ul>.
- Other consecutive lines form one paragraph, <p>LINES</p>, joined with one space.
- Blocks are joined with \n. Empty or whitespace-only text, or a value that is not a string, renders as an empty string.

Inline (paragraphs and list items). Scan the text from left to right. At each position try, in this order: a code span `X` (X = one or more characters other than `), a link [TEXT](URL) (TEXT = one or more characters other than ], URL = one or more characters other than ) and whitespace), bold **X** (X = one or more characters other than *). The first one that matches is rendered and the scan continues after it; any other character is plain text. Spans do not nest: X, TEXT and URL are only escaped.
- code span: <code>X</code>; bold: <strong>X</strong>
- link: <a href="URL" rel="noopener noreferrer">TEXT</a>, but only when URL starts with http:// or https:// in any letter case; any other link renders as its TEXT alone.

Escaping. Every character of the model''s text that reaches the output is escaped once: & as &amp;, < as &lt;, > as &gt;, " as &quot; and '' as &#39; (plain text, code, link text and URL alike). The only tags in the output are the ones listed above.

Input (stdin, JSON): an array of up to 400 model outputs. Output (printed by the test runner): "=== feedback <n> ===" and the HTML for each. Do not change the test runner. The public tests are ordinary feedback and pass on the assistant''s code; the hidden tests are XSS payloads, other link schemes and tricky escapes.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
