INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 1, 'The model''s feedback contains <img src=x onerror=...>. Which line of renderFeedback decides whether the browser receives a tag or the visible text "<img"? And which URLs does the link rule turn into an href?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 2, 'Look at inline(): it builds HTML by replacing parts of the raw text, so everything it does not replace - plain text, the content of a code span, the URL - reaches the page as it is. The code block content is joined and inserted the same way. Then look at the link pattern: what does it check about the URL?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 3, 'A similar case in a comment widget that allows only links: for the text `Hi <b>you</b> [me](javascript:x)` the renderer finds one link and two pieces around it. The piece before it is written as `Hi &lt;b&gt;you&lt;/b&gt; `, the link fails the http/https check so only `me` is written, and the empty piece after it adds nothing. Each piece is escaped exactly once, at the moment it is written to the output, so an `&` never becomes `&amp;amp;`.');
