-- challenge chal_quiz_lle_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_421', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-4-2' AND is_deleted = false LIMIT 1), 'solution-leak-quiz', 'What does a fingerprint match prove?', 'Two results of the solution leak check on the grading feedback: what winnowing guarantees to find, and what a low overlap does not prove.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_421'), 'The leak check fingerprints code with K = 5 (characters per k-gram, after removing whitespace and lowering case) and W = 4 (hashes per window, the minimum of each window is kept).

Reference solution (normalised, excerpt):  ...while(dayset.has(runend+1))runend++;...
Feedback code block (normalised):           if(x)while(dayset.has(runend+1))y();

The shared run "while(dayset.has(runend+1))" is 27 characters long.

Statement: "The block and the reference share at least one fingerprint value, because winnowing keeps at least one hash from every shared run of W + K - 1 = 8 or more characters."', 'single_choice'::question_type, 'True. A shared run of 8 characters contains 4 consecutive k-grams of length 5, which is one full window of W hashes, and the same window of hashes appears in both texts. Each text keeps the minimum of that window, and both minimums are the same value, so they share at least one fingerprint. The 27-character run is far above the guarantee threshold. Below 8 characters nothing is guaranteed, and runs shorter than K are invisible: that is why winnowing ignores small coincidences such as a shared keyword. The misconception is that winnowing samples hashes at random and may miss a long copy; the window minimum makes the selection depend only on the content, so a long enough copy is always caught.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_421'), 'Feedback block (the reference solution with every variable renamed: daySet -> active, runEnd -> last, best -> top):

for (const day of active) {
  if (active.has(day - 1)) continue;
  let last = day;
  while (active.has(last + 1)) last++;
  if (!top || last - day > top[1] - top[0]) top = [day, last];
}

Leak check result: code-overlap 0.16 with solution 1 (threshold 0.5), no hidden output found, step rule not applicable (no list) -> allowed

Statement: "The overlap of 0.16 shows that this feedback does not reveal the reference algorithm."', 'single_choice'::question_type, 'False. Character fingerprints measure how much of the reference text is copied, not whether the algorithm is revealed. Renaming every variable breaks most k-grams, so the overlap drops below the threshold, but the block is still the complete reference algorithm. The check has a false negative here, and every output check has some: normalising identifiers before fingerprinting (as plagiarism tools do), sampling allowed feedback for human review, and keeping a set of known leaks in the eval set are how you find and measure them. The misconception is that a score below the threshold proves safety; it only proves this rule did not fire.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_lle_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_lle_422', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-4-2' AND is_deleted = false LIMIT 1), 'detect-leaked-solutions', 'Block feedback that leaks hidden tests or the reference solution', 'CodeDev''s AI grading assistant explains why a submission failed. To grade, it sees the challenge''s reference solutions (one per language) and every test case, hidden ones included, so its feedback can leak them: last week learners shared feedback that quoted hidden expected outputs, pasted a reformatted reference solution, and listed the reference algorithm step by step. Write checkFeedback(feedback, refs), the check that runs after generation and before the feedback is stored. It returns "allowed" or the first rule that fires, in this order:

normalise(text) = the text in lower case with every whitespace character removed.

1. hidden-output: for each test in order (numbered from 1, public ones included in the numbering), when the test is hidden and normalise(expected) has at least MIN_OUTPUT_LENGTH (6) characters and normalise(feedback) contains it, return "blocked: hidden-output (test <n>)". Public outputs are allowed: the learner already sees them.

2. code-overlap: code blocks are the lines between a line that starts with ``` (after trimming) and the next such line, or the end of the text when the block is not closed; their lines are joined with \n. The winnowed fingerprint of a piece of code: t = normalise(code); for every i with i + K <= t.length, the k-gram t.slice(i, i + K) gets the hash h = 0, then for each of its characters h = (h * 31 + charCode) % 1000000007; for every window of W consecutive hashes (start 0, 1, ... up to hashes.length - W), take the minimum hash; when there are fewer than W hashes, the single window is all of them; no k-grams gives an empty fingerprint. The fingerprint is the set of the selected hash values. overlap(block, solution) = (values in both fingerprints) / (size of the solution''s fingerprint); solutions with an empty fingerprint are skipped. Take the highest overlap over every block and every solution (the first solution on a tie, counting solutions from 1); when it is >= MAX_OVERLAP (0.5), return "blocked: code-overlap (solution <n>, <overlap with 2 decimals, toFixed(2)>)".

3. algorithm-steps: step lines are the lines outside code blocks that, after trimming, start with - or * or digits and a dot, followed by whitespace. An identifier from refs.distinctive is found when it appears in a step line as a whole word (case-sensitive, not preceded or followed by a letter, digit, _ or $). When found identifiers >= min(MIN_IDENTIFIERS (3), number of distinctive identifiers) and that number is above 0, return "blocked: algorithm-steps (<found identifiers in the order of refs.distinctive, joined with ", ">)".

Feedback that is not a string, or is empty or only whitespace, returns "blocked: empty" (fail closed) before any rule. Otherwise, when no rule fires, return "allowed".

Input (stdin, JSON): { "solutions": [up to 5 strings], "tests": [{ "expected": string, "hidden": boolean }], "distinctive": [strings], "feedback": [up to 200 values] }. Output (printed by the test runner): "feedback <n>: <verdict>" per feedback. Do not change the policy constants or the test runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
