INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 1, 'Which of the three rules needs the text exactly as written (line by line), and which ones compare normalised text? Write normalise and fingerprint first and check them on a small string by hand.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 2, 'Look at three places: the hidden flag of each test (public outputs never block), the denominator of the overlap (the reference fingerprint, so quoting one line of the reference stays small), and how an identifier is matched (a whole word, so daySetSize is not daySet).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 3, 'A worked example on other input, with K = 3 and W = 2: normalise("Ab c d") = "abcd", the k-grams are "abc" and "bcd", and their hashes are (97*31 + 98)*31 + 99 = 96354 and (98*31 + 99)*31 + 100 = 97347. There are 2 hashes and W = 2, so there is one window and the fingerprint is { 96354 }. The text "xbcd" has the hashes 118457 and 97347, so its fingerprint is { 97347 }: the two fingerprints share no value (overlap 0 / 1 = 0) although both texts contain "bcd". Texts this short are below the winnowing guarantee; compare sets of hash values, never positions.');
