INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'Ordinary feedback passes; a hidden test output quoted verbatim is blocked', '{"solutions":["function longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}","def longest_streak(days):\n    day_set = set(days)\n    best = None\n    for day in sorted(day_set):\n        if day - 1 in day_set:\n            continue\n        run_end = day\n        while run_end + 1 in day_set:\n            run_end += 1\n        if best is None or run_end - day > best[1] - best[0]:\n            best = (day, run_end)\n    return best"],"tests":[{"expected":"streak 2026-01-05..2026-01-07 (3 days)","hidden":false},{"expected":"none","hidden":false},{"expected":"streak 2026-02-27..2026-03-02 (4 days)","hidden":true},{"expected":"streak 2025-12-30..2026-01-02 (4 days)","hidden":true},{"expected":"none","hidden":true}],"distinctive":["daySet","runEnd","day_set","run_end","isStreakStart"],"feedback":["Your function returns the right streak for the first public test. Check what happens when the same day appears twice in the input.","Close! For hidden test 3 the expected output is streak 2026-02-27..2026-03-02 (4 days), but you return 3 days.","The public test expects streak 2026-01-05..2026-01-07 (3 days) and your output matches it."]}', '"feedback 1: allowed\nfeedback 2: blocked: hidden-output (test 3)\nfeedback 3: allowed"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'A copied code block and a step list that retells the reference algorithm', '{"solutions":["function longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}","def longest_streak(days):\n    day_set = set(days)\n    best = None\n    for day in sorted(day_set):\n        if day - 1 in day_set:\n            continue\n        run_end = day\n        while run_end + 1 in day_set:\n            run_end += 1\n        if best is None or run_end - day > best[1] - best[0]:\n            best = (day, run_end)\n    return best"],"tests":[{"expected":"streak 2026-01-05..2026-01-07 (3 days)","hidden":false},{"expected":"none","hidden":false},{"expected":"streak 2026-02-27..2026-03-02 (4 days)","hidden":true},{"expected":"streak 2025-12-30..2026-01-02 (4 days)","hidden":true},{"expected":"none","hidden":true}],"distinctive":["daySet","runEnd","day_set","run_end","isStreakStart"],"feedback":["Here is a cleaner version:\n```ts\nfunction longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}\n```","Follow these steps:\n1. Put the days in a `daySet`\n2. Skip a day unless `isStreakStart` is true for it\n3. Move `runEnd` forward while the next day is in the set\n4. Keep the longest run","Good structure. Two things to look at:\n- the loop stops one day too early when a streak ends on the last day\n- an empty list should print none\n\nYour current line:\n```ts\nfor (let i = 1; i < days.length; i++) {\n```"]}', '"feedback 1: blocked: code-overlap (solution 1, 1.00)\nfeedback 2: blocked: algorithm-steps (daySet, runEnd, isStreakStart)\nfeedback 3: allowed"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'Hidden outputs match after case and whitespace normalisation; short and public ones do not count', '{"solutions":["function denseRanks(rows: Row[]): string[] {\n  const sortedRows = [...rows].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));\n  const lines: string[] = [];\n  let rank = 0;\n  let previousScore: number | null = null;\n  for (const row of sortedRows) {\n    if (row.score !== previousScore) {\n      rank++;\n      previousScore = row.score;\n    }\n    lines.push(`rank ${rank}: ${row.name} (${row.score})`);\n  }\n  return lines;\n}","def dense_ranks(rows):\n    sorted_rows = sorted(rows, key=lambda r: (-r[\"score\"], r[\"name\"]))\n    lines, rank, previous_score = [], 0, None\n    for row in sorted_rows:\n        if row[\"score\"] != previous_score:\n            rank += 1\n            previous_score = row[\"score\"]\n        lines.append(f\"rank {rank}: {row[''name'']} ({row[''score'']})\")\n    return lines"],"tests":[{"expected":"rank 1: ana (980)\nrank 2: binh (975)","hidden":false},{"expected":"rank 1: ana (980)\nrank 2: binh (975)\nrank 2: chi (975)\nrank 3: dung (960)","hidden":true},{"expected":"[]","hidden":true},{"expected":"rank 1: zoe (7)\nrank 1: yen (7)","hidden":true}],"distinctive":["sortedRows","previousScore","sorted_rows","previous_score","localeCompare"],"feedback":["Expected:\nRANK 1: Ana (980)   rank 2: Binh (975)\nrank 2: chi (975)\n\nrank 3: dung (960)","Your output for the public test, rank 1: ana (980) rank 2: binh (975), is correct.","When the input is empty you should print [] instead of crashing.","For the tie case expect rank 1: zoe (7)\n  rank 1: yen (7) in that order.","The leaderboard test fails because two learners with the same score get different ranks. Read the task again: equal scores share a rank."]}', '"feedback 1: blocked: hidden-output (test 2)\nfeedback 2: allowed\nfeedback 3: allowed\nfeedback 4: blocked: hidden-output (test 4)\nfeedback 5: allowed"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'Reformatted, commented and partial copies are blocked; a one-line quote and renamed code are not', '{"solutions":["function longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}","def longest_streak(days):\n    day_set = set(days)\n    best = None\n    for day in sorted(day_set):\n        if day - 1 in day_set:\n            continue\n        run_end = day\n        while run_end + 1 in day_set:\n            run_end += 1\n        if best is None or run_end - day > best[1] - best[0]:\n            best = (day, run_end)\n    return best"],"tests":[{"expected":"streak 2026-01-05..2026-01-07 (3 days)","hidden":false},{"expected":"none","hidden":false},{"expected":"streak 2026-02-27..2026-03-02 (4 days)","hidden":true},{"expected":"streak 2025-12-30..2026-01-02 (4 days)","hidden":true},{"expected":"none","hidden":true}],"distinctive":["daySet","runEnd","day_set","run_end","isStreakStart"],"feedback":["Compare with this:\n```python\ndef longest_streak( days ):\n  day_set=set( days )\n  best=None\n\n  for day in sorted( day_set ):\n    if day-1 in day_set:\n      continue\n    run_end=day\n    while run_end+1 in day_set:\n      run_end+=1\n    if best is None or run_end-day>best[1]-best[0]:\n      best=(day,run_end)\n  return best\n```","The fix, with comments:\n```ts\nfunction longestStreak(days: number[]): [number, number] | null {\n  // a Set makes each lookup O(1)\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    // walk to the end of this run\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}\n```","Start like this and finish the loop yourself:\n```ts\nfunction longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n```","This line is the key:\n```ts\nwhile (daySet.has(runEnd + 1)) runEnd++;\n```","Hint:\n```ts\nfunction streak(days: number[]): [number, number] | null {\n  const active = new Set(days);\n  let top: [number, number] | null = null;\n  for (const day of active) {\n    const first = !active.has(day - 1);\n    if (!first) continue;\n    let last = day;\n    while (active.has(last + 1)) last++;\n    if (!top || last - day > top[1] - top[0]) top = [day, last];\n  }\n  return top;\n}\n```","Unclosed block:\n```python\ndef longest_streak(days):\n    day_set = set(days)\n    best = None\n    for day in sorted(day_set):\n        if day - 1 in day_set:\n            continue\n        run_end = day\n        while run_end + 1 in day_set:\n            run_end += 1\n        if best is None or run_end - day > best[1] - best[0]:\n            best = (day, run_end)\n    return best"]}', '"feedback 1: blocked: code-overlap (solution 2, 1.00)\nfeedback 2: blocked: code-overlap (solution 1, 0.97)\nfeedback 3: blocked: code-overlap (solution 1, 0.63)\nfeedback 4: allowed\nfeedback 5: allowed\nfeedback 6: blocked: code-overlap (solution 2, 1.00)"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'Identifiers count only as whole words, only in step lines, and three are needed', '{"solutions":["function longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}","def longest_streak(days):\n    day_set = set(days)\n    best = None\n    for day in sorted(day_set):\n        if day - 1 in day_set:\n            continue\n        run_end = day\n        while run_end + 1 in day_set:\n            run_end += 1\n        if best is None or run_end - day > best[1] - best[0]:\n            best = (day, run_end)\n    return best"],"tests":[{"expected":"streak 2026-01-05..2026-01-07 (3 days)","hidden":false},{"expected":"none","hidden":false},{"expected":"streak 2026-02-27..2026-03-02 (4 days)","hidden":true},{"expected":"streak 2025-12-30..2026-01-02 (4 days)","hidden":true},{"expected":"none","hidden":true}],"distinctive":["daySet","runEnd","day_set","run_end","isStreakStart"],"feedback":["You could keep a daySet, track runEnd and compute isStreakStart, but first fix the off-by-one.","Next steps:\n- print daySetSize before the loop\n- remove the unseen runEnds from the log\n- check isStreakStarted is reset","Next steps:\n- your daySet is fine\n- `runEnd` is never reset\n- add a test with one day","Next steps:\n* build day_set from the input\n* advance run_end while the next day exists\n* compare with your daySet version"]}', '"feedback 1: allowed\nfeedback 2: allowed\nfeedback 3: allowed\nfeedback 4: blocked: algorithm-steps (daySet, day_set, run_end)"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'Rule order, the solution with the highest overlap, and fewer than three identifiers', '{"solutions":["function denseRanks(rows: Row[]): string[] {\n  const sortedRows = [...rows].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));\n  const lines: string[] = [];\n  let rank = 0;\n  let previousScore: number | null = null;\n  for (const row of sortedRows) {\n    if (row.score !== previousScore) {\n      rank++;\n      previousScore = row.score;\n    }\n    lines.push(`rank ${rank}: ${row.name} (${row.score})`);\n  }\n  return lines;\n}","def dense_ranks(rows):\n    sorted_rows = sorted(rows, key=lambda r: (-r[\"score\"], r[\"name\"]))\n    lines, rank, previous_score = [], 0, None\n    for row in sorted_rows:\n        if row[\"score\"] != previous_score:\n            rank += 1\n            previous_score = row[\"score\"]\n        lines.append(f\"rank {rank}: {row[''name'']} ({row[''score'']})\")\n    return lines"],"tests":[{"expected":"rank 1: ana (980)\nrank 2: binh (975)","hidden":false},{"expected":"rank 1: ana (980)\nrank 2: binh (975)\nrank 2: chi (975)\nrank 3: dung (960)","hidden":true},{"expected":"[]","hidden":true},{"expected":"rank 1: zoe (7)\nrank 1: yen (7)","hidden":true}],"distinctive":["previousScore","sortedRows"],"feedback":["Expected rank 1: zoe (7) rank 1: yen (7). Reference:\n```ts\nfunction denseRanks(rows: Row[]): string[] {\n  const sortedRows = [...rows].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));\n  const lines: string[] = [];\n  let rank = 0;\n  let previousScore: number | null = null;\n  for (const row of sortedRows) {\n    if (row.score !== previousScore) {\n      rank++;\n      previousScore = row.score;\n    }\n    lines.push(`rank ${rank}: ${row.name} (${row.score})`);\n  }\n  return lines;\n}\n```","Part of it:\n```ts\nfunction denseRanks(rows: Row[]): string[] {\n  const sortedRows = [...rows].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));\n  const lines: string[] = [];\n  let rank = 0;\n```\nand the Python one:\n```python\ndef dense_ranks(rows):\n    sorted_rows = sorted(rows, key=lambda r: (-r[\"score\"], r[\"name\"]))\n    lines, rank, previous_score = [], 0, None\n    for row in sorted_rows:\n        if row[\"score\"] != previous_score:\n            rank += 1\n            previous_score = row[\"score\"]\n        lines.append(f\"rank {rank}: {row[''name'']} ({row[''score'']})\")\n    return lines\n```","Steps:\n1. sort into sortedRows\n2. compare with previousScore","Steps:\n1. sort the rows\n2. compare with previousScore"]}', '"feedback 1: blocked: hidden-output (test 4)\nfeedback 2: blocked: code-overlap (solution 2, 1.00)\nfeedback 3: blocked: algorithm-steps (previousScore, sortedRows)\nfeedback 4: allowed"', 3, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_lle_422'), 'Empty, null and whitespace feedback, an empty reference and an empty expected output', '{"solutions":["","   "],"tests":[{"expected":"","hidden":true},{"expected":"   \n","hidden":true}],"distinctive":[],"feedback":["","  \n\t ",null,"Steps:\n1. a\n2. b\n3. c\n```ts\nfunction longestStreak(days: number[]): [number, number] | null {\n  const daySet = new Set(days);\n  let best: [number, number] | null = null;\n  for (const day of daySet) {\n    const isStreakStart = !daySet.has(day - 1);\n    if (!isStreakStart) continue;\n    let runEnd = day;\n    while (daySet.has(runEnd + 1)) runEnd++;\n    if (!best || runEnd - day > best[1] - best[0]) best = [day, runEnd];\n  }\n  return best;\n}\n```","Fine."]}', '"feedback 1: blocked: empty\nfeedback 2: blocked: empty\nfeedback 3: blocked: empty\nfeedback 4: allowed\nfeedback 5: allowed"', 3, false, true, 7),
