WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-lle-4-3' AND is_deleted = false);

-- challenge chal_quiz_lle_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_lle_431', (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'llm-evaluation-guardrails') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-lle-4-3' AND is_deleted = false LIMIT 1), 'guardrails-in-production-quiz', 'Read the guardrails after a bad prompt release', 'Evidence from the grade-v14 release of the AI grading assistant: the retry policy, a review of what an input filter blocked, and the rollback. Decide what each one shows.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431'), 'Grading worker during the grade-v14 release:

config:
  maxAttemptsPerSubmission: 6     # 1 call + up to 5 retries when the output fails schema validation
  max_tokens: 1200

trace summary 18:05-19:30 (prompt_version = grade-v14):
  submissions graded:   4,180
  model calls:         17,904   (4.3 per submission)
  schema failures:      38% of calls

Proposed change: maxAttemptsPerSubmission: 2; after the second failure, publish the tests-only score with the neutral feedback text.

Statement: "With the proposed change, a release like grade-v14 can make at most 2 model calls per submission, whatever share of its outputs fail validation."', 'single_choice'::question_type, 'True. The attempt limit is a budget enforced by the worker, not by the model: after the second failed validation the worker stops calling and uses the fallback, so the number of calls per submission is bounded by 2 no matter how bad the prompt is. With the old limit of 6, a prompt that breaks the output format multiplies traffic and cost, which is exactly the 4.3 calls per submission in the trace (OWASP LLM10, Unbounded Consumption). The misconception is that retries fix bad output: a schema failure caused by the prompt repeats on most retries, so extra attempts mostly buy cost and latency. Pair the per-submission budget with a feature-wide spend cap and an alert on the validation failure rate.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431'), 'Input guardrail "injection-phrases" (blocks a submission that contains phrases such as "ignore previous instructions"), last 30 days:

  submissions checked:  48,200
  blocked:               1,012   (2.1%)

A reviewer labelled 200 blocked submissions chosen at random:
  real attempts to steer the grader:   52
  benign (string literals in the Prompt Engineering course, comments quoting a lesson): 148

Statement: "About three quarters of the submissions this filter blocks are false positives, so its 2.1% block rate says little about how accurate it is."', 'single_choice'::question_type, 'True. In the labelled sample 148 of 200 blocks were benign, 74%, so roughly three out of four blocked learners did nothing wrong; with 1,012 blocks a month that is several hundred honest submissions. The block rate only says how often the filter fires, not whether it is right: a filter that blocks 2% at random would have the same rate. To judge a guardrail you need labelled samples of what it blocks (precision) and of what it lets through (missed attacks), measured per rule. Here the right move is to stop using the phrase match as a gate and use it as a signal that routes to review, or to scope it per course. The misconception is that a low block rate means few false positives.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431') AND order_index = 2)
    RETURNING id
)
