        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431'), 'Incident log, grade-v14:

19:40  GRADING_PROMPT_VERSION switched to grade-v13 (feature flag, no deploy)
19:41  new gradings: prompt_version = grade-v13, schema failures 1.2%, calls per submission 1.02

SELECT count(*) AS graded, count(*) FILTER (WHERE published_status = ''passed'') AS published_passed
FROM grading_result WHERE prompt_version = ''grade-v14'';

 graded | published_passed
--------+-----------------
   4180 |             612

Statement: "Once the flag switch at 19:41 shows healthy numbers, the incident is resolved: the submissions graded with grade-v14 need no further action because every new grading uses grade-v13."', 'single_choice'::question_type, 'False. The rollback stops new damage; it does not repair the 4,180 results already produced by grade-v14, 612 of which were published as passed with scores the team no longer trusts. Incident response continues: find the affected results through the prompt_version recorded with each grading (this is why traces carry it), re-grade or send them to human review, correct and notify where a published result changes, and only then close the incident with a postmortem that adds the failing cases to the eval set and the regression gate. The misconception is that reverting a change reverts its effects; stored decisions stay wrong until you fix them.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_lle_431') AND order_index = 3)
    RETURNING id
)
